import logging
import six
from abc import ABCMeta, abstractmethod
import time


@six.add_metaclass(ABCMeta)
class ActionVerifiable(object):

    @abstractmethod
    def execute(self, timeout=None, interval=1.0, **kwargs):
        pass

    def verify(self):
        pass


class ActionSequenceVerifiable(ActionVerifiable):

    def execute(self, timeout=None, interval=1, **kwargs):
        commands = self._generate_command_sequence()
        for cmd in commands:
            logging.info('Command instance: {}.'.format(cmd))
            cmd.execute()
            time.sleep(interval)
        logging.info('All commands execute successfully.')

    @abstractmethod
    def _generate_command_sequence(self):
        raise NotImplementedError
